function renderStats(){const e=document.getElementById("stats-grid");e&&"undefined"!=typeof MALABAR_FROG_INFO&&(e.innerHTML=MALABAR_FROG_INFO.quickStats.map(e=>`\n        <div class="stat-card">\n            <span class="stat-icon">${e.icon}</span>\n            <div class="stat-val">${e.value}</div>\n            <div class="stat-lbl">${e.label}</div>\n        </div>\n    `).join(""))}function renderTaxonomy(){const e=document.getElementById("taxonomy-grid");e&&"undefined"!=typeof TAXONOMY_DATA&&(e.innerHTML=Object.entries(TAXONOMY_DATA).map(([e,n])=>`\n        <div class="tax-card">\n            <span class="tax-lbl">${e.toUpperCase()}:</span>\n            <span class="tax-val">${n}</span>\n        </div>\n    `).join(""))}function renderEcology(){if("undefined"==typeof ECOLOGY_BEHAVIOUR)return;const e=document.getElementById("eco-overview"),n=document.getElementById("eco-dist"),t=document.getElementById("eco-habitat"),o=document.getElementById("eco-morph"),r=document.getElementById("eco-behaviour"),i=document.getElementById("eco-diet"),d=document.getElementById("eco-repro"),a=document.getElementById("eco-importance"),c=document.getElementById("eco-conserve");e&&(e.innerHTML=`<strong>Overview:</strong> ${ECOLOGY_BEHAVIOUR.overview}`),n&&(n.innerHTML=`<strong>Geographic Distribution:</strong> ${ECOLOGY_BEHAVIOUR.distribution}`),t&&(t.innerHTML=`<strong>Canopy Habitat:</strong> ${ECOLOGY_BEHAVIOUR.habitat}`),o&&(o.innerHTML=`<strong>Morphology & Webbing:</strong> ${ECOLOGY_BEHAVIOUR.morphology}`),r&&(r.innerHTML=`<strong>Aerial Gliding Behaviour:</strong> ${ECOLOGY_BEHAVIOUR.behaviour}`),i&&(i.innerHTML=`<strong>Diet & Hunting:</strong> ${ECOLOGY_BEHAVIOUR.diet}`),d&&(d.innerHTML=`<strong>Monsoon Foam Nesting:</strong> ${ECOLOGY_BEHAVIOUR.reproduction}`),a&&(a.innerHTML=`<strong>Ecological Importance:</strong> ${ECOLOGY_BEHAVIOUR.ecologicalImportance}`),c&&(c.innerHTML=`<strong>Conservation Status:</strong> ${ECOLOGY_BEHAVIOUR.conservation}`)}function renderFacts(){const e=document.getElementById("facts-grid");e&&"undefined"!=typeof INTERESTING_FACTS&&(e.innerHTML=INTERESTING_FACTS.map(e=>`\n        <div class="fact-card">\n            <h3>✨ ${e.title}</h3>\n            <p>${e.description}</p>\n        </div>\n    `).join(""))}function renderGallery(){const e=document.getElementById("gallery-grid");e&&"undefined"!=typeof GALLERY_IMAGES&&(e.innerHTML=GALLERY_IMAGES.map(e=>`\n        <div class="gallery-card">\n            <img src="${e.url}" alt="${e.caption}" loading="lazy" />\n            <p>${e.caption}</p>\n        </div>\n    `).join(""))}function renderReferences(){const e=document.getElementById("references-list");e&&"undefined"!=typeof REFERENCES&&(e.innerHTML=REFERENCES.map(e=>`\n        <li>\n            <a href="${e.link}" target="_blank" rel="noopener noreferrer">📚 ${e.text}</a>\n        </li>\n    `).join(""))}function initThemeToggle(){const e=document.getElementById("theme-toggle");e&&e.addEventListener("click",()=>{const n=document.body.classList.toggle("light-theme");localStorage.setItem("theme",n?"light":"dark"),e.textContent=n?"🌙":"☀️"})}document.addEventListener("DOMContentLoaded",()=>{renderStats(),renderTaxonomy(),renderEcology(),renderFacts(),renderGallery(),renderReferences(),initThemeToggle()});